SELECT EXISTS
        (
        SELECT 1
          FROM MEMBER_INFO
         WHERE USER_EMAIL = #{email}
        )

SELECT EXISTS (
    SELECT 1 FROM MEMBER_INFO WHERE USER_ID = #{userId}
)

SELECT EXISTS (
    SELECT 1 FROM MEMBER_INFO WHERE USER_NAME = #{userName}
)

SELECT EXISTS (
    SELECT 1 FROM MEMBER_INFO 
     WHERE USER_ID = #{userId} 
       AND USER_EMAIL = #{email}
)

mapper.insert:
