                        , CREATE_AT
                        , UPDATE_AT
                        )
    VALUES              ( #{memberId}
                        , #{userId}
                        , #{userPass}
                        , #{userName}
                        , #{userEmail}
                        , #{emailVerified}
                        , #{userRole}
                        , #{userStatus}
                        , NOW()
                        , NOW()
)

mapper.update:
